package fixture;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.world.item.ItemStack;import de.maxhenkel.corpse.corelib.item.ItemUtils;public class EquipmentProbe{public static void main(String[]args){Game.Level p=new Game.Level();NonNullList<ItemStack>before=NonNullList.withSize(7,ItemStack.EMPTY);before.set(5,new ItemStack("helmet",1,"saved-components"));CompoundTag tag=new CompoundTag();ItemUtils.saveItemList(p,tag,"Equipment",before);NonNullList<ItemStack>after=NonNullList.withSize(7,ItemStack.EMPTY);ItemUtils.readItemList(p,tag,"Equipment",after);CompoundTag items=new CompoundTag();ItemUtils.saveItemList(p,items,"Items",before);if(items.getList("Items",10).size()!=1)throw new AssertionError("ordinary item lists changed");System.out.println("HELMET_SLOT="+(after.get(5).id.equals("helmet")?5:after.get(0).id.equals("helmet")?0:-1));}}
